checks.command:
node -e 'const prettier = require("./src/index.cjs"); (async () => { const input = `condition ? ifTrue
: [
      // Hello, world!
  ]
`; const output = await prettier.format(input, { parser: "babel", tabWidth: 4, semi: false, experimentalTernaries: true }); const count = (output.match(/Hello, world!/g) || []).length; if (count !== 2) { console.error(output); throw new Error(`expected start commit to duplicate the comment twice, saw ${count}`); } })().catch((error) => { console.error(error); process.exit(1); })'

node -e 'const prettier = require("./src/index.cjs"); (async () => { const cases = [`condition ? ifTrue
: [
      // Hello, world!
  ]
`, `condition ? [
      // Hello, world!
  ]
: ifFalse
`, `condition ? ifTrue
: {
      // Hello, world!
  }
`, `condition ? {
    // Hello, world!
  }
: ifFalse
`, `condition ? ifTrue
: [
      // Hello, world!
    1,
  ]
`]; for (const input of cases) { const output = await prettier.format(input, { parser: "babel", tabWidth: 4, semi: false, experimentalTernaries: true }); const count = (output.match(/Hello, world!/g) || []).length; if (count !== 1) { console.error(output); throw new Error(`expected exactly one preserved comment, saw ${count}`); } } })().catch((error) => { console.error(error); process.exit(1); })'

